import {getRoadmaps,getExtraRoadmaps} from './roadmaps';
import {getCatalogCards} from './catalog';
import {teachers} from './teachers';

export type DetailRoute={kind:string;id:string;source:string;sourcePage:number};
export type DetailContent={title:string;eyebrow:string;summary:string;image:string;imageAlt:string;notice:string;sections:{title:string;body:string}[];steps?:string[];stepTitle?:string;catalogIndex?:number;destination:string;destinationLabel:string;context:string;externalUrl?:string};
export const sourceLabels:Record<string,string>={home:'Trang chủ',roadmaps:'Danh sách lộ trình',classes:'Lớp học Toán',materials:'Tài liệu',practice:'Luyện đề',teachers:'Giáo viên đồng hành'};
export function readDetailRoute(params:URLSearchParams):DetailRoute{return {kind:params.get('loai')??'',id:params.get('id')??'',source:Object.hasOwn(sourceLabels,params.get('tu')??'')?params.get('tu')!:'home',sourcePage:params.get('trang')==='2'?2:1};}
export const topicIds=['so-dai-so','hinh-hoc','thong-ke-xac-suat','toan-cuoc-song'];
const topicNames=['Số và Đại số','Hình học và Đo lường','Thống kê và Xác suất','Toán trong cuộc sống'];
const previewNotice='Nội dung minh họa, chờ giáo viên thẩm định. Chưa có học liệu, đăng ký hoặc hoạt động học tập thật trên trang này.';
const serviceDetails:Record<string,Omit<DetailContent,'context'>>={
 chocon:{title:'Kết nối cùng chocon',eyebrow:'KHÁM PHÁ HỆ SINH THÁI',summary:'Hệ thống quản lý, giám sát, giáo dục con sử dụng máy tính và bảo vệ con trên môi trường mạng.',image:'/assets/toan/family-v3.webp',imageAlt:'Minh họa gia đình cùng tìm hiểu việc học',notice:'Chưa có đường dẫn chocon chính thức được xác nhận. Trang này không chuyển tới website ngoài, không đăng nhập và không chia sẻ dữ liệu.',sections:[{title:'Trạng thái liên kết',body:'Lối tắt chocon đã có trong bố cục. Quản trị viên cần cung cấp và xác minh địa chỉ chính thức trước khi bật điều hướng.'},{title:'Định hướng đồng hành cùng gia đình',body:'Theo mô tả do chủ hệ thống cung cấp, chocon hướng đến việc quản lý, giám sát, giáo dục con sử dụng máy tính và bảo vệ con trên môi trường mạng. Việc tích hợp, quyền truy cập và cách vận hành thực tế chưa được kiểm chứng trong bản xem trước.'}],destination:'roadmaps',destinationLabel:'Khám phá lộ trình Toán'},
 sat:{title:'Ôn luyện Tiếng Anh',eyebrow:'MỞ RỘNG CƠ HỘI',summary:'Mở ra cơ hội giao tiếp quốc tế và ôn thi chuyên.',image:'/assets/toan/exam-v3.webp',imageAlt:'Minh họa học sinh ôn tập và mở rộng cơ hội học tập',notice:'Mục SAT trước đây đã được thay bằng Ôn luyện Tiếng Anh. Liên kết chính thức do chủ hệ thống cung cấp; tính năng và chương trình trên website ngoài chưa được kiểm chứng từ trang này.',sections:[{title:'Hướng học tập mở rộng',body:'Tìm hiểu định hướng ôn luyện Tiếng Anh cho giao tiếp quốc tế và ôn thi chuyên tại website Tiếng Anh Ôn Thi 360.'},{title:'Trước khi chuyển website',body:'Liên kết mở trong tab mới. Trang Toán không tự đăng nhập, gửi thông tin cá nhân hoặc đăng ký dịch vụ ở website Tiếng Anh.'}],externalUrl:'https://tienganh.onthi360.vn',destination:'roadmaps',destinationLabel:'Xem lộ trình Toán'},
 companion:{title:'Đồng hành cùng con học Toán',eyebrow:'DÀNH CHO PHỤ HUYNH',summary:'Lắng nghe cách con nghĩ, cùng chọn một mục tiêu nhỏ và ghi nhận nỗ lực mỗi ngày.',image:'/assets/toan/family-v3.webp',imageAlt:'Minh họa phụ huynh cùng con học Toán',notice:'Các gợi ý dưới đây chỉ là nội dung tham khảo. Không gian phụ huynh chưa kết nối tài khoản, lịch học hay dữ liệu học sinh thật.',sections:[{title:'Bắt đầu từ một cuộc trò chuyện',body:'Có thể hỏi con đang học chủ đề nào, phần nào con thấy dễ và điều gì con muốn được giải thích thêm. Đây là gợi ý đồng hành, không phải đánh giá năng lực.'},{title:'Chọn mục tiêu vừa sức',body:'Cùng xem một lộ trình theo lớp hiện tại, chọn một bước để tìm hiểu và dành thời gian nghe con tự giải thích cách làm.'},{title:'Không gian phụ huynh đang chuẩn bị',body:'Mục tiêu học tập, lịch học và phản hồi chỉ có thể hiển thị khi có dữ liệu thật và liên kết giám hộ hợp lệ. Bản xem trước không thực hiện liên kết này.'}],destination:'roadmaps',destinationLabel:'Cùng con xem lộ trình'},
 consultation:{title:'Chuẩn bị kết nối tư vấn',eyebrow:'LẮNG NGHE VÀ ĐỊNH HƯỚNG',summary:'Tìm hiểu thông tin cần chuẩn bị trước khi trao đổi về lộ trình học Toán.',image:'/assets/toan/consultation-v3.webp',imageAlt:'Minh họa tư vấn viên hỗ trợ định hướng học tập',notice:'Kênh tư vấn chính thức chưa được cấu hình. Trang này không nhận yêu cầu, không thu thập thông tin cá nhân và không gửi tin nhắn.',sections:[{title:'Điều bạn muốn được giải đáp',body:'Có thể chuẩn bị lớp đang học, chủ đề cần tìm hiểu và mục tiêu học tập. Không nhập hoặc gửi thông tin cá nhân thật vào bản xem trước.'},{title:'Các kênh liên hệ',body:'Điện thoại, email, địa chỉ và giờ hỗ trợ đang chờ xác minh. Trang Liên hệ hiển thị trạng thái hiện tại, không cung cấp kênh liên hệ giả.'},{title:'Trong thời gian chờ',body:'Bạn có thể xem lộ trình và các danh mục minh họa để hình dung cấu trúc học tập. Những nội dung này chưa thay thế tư vấn chuyên môn hoặc dịch vụ đã phát hành.'}],destination:'contact',destinationLabel:'Xem thông tin liên hệ'},
};

export function getDetailContent(kind:string,id:string,grade:number):DetailContent|null{
 if(kind==='roadmap'){
  const roadmap=[...getRoadmaps(grade),...getExtraRoadmaps(grade)].find(r=>r.id===id);if(!roadmap)return null;
  return {title:roadmap.title,eyebrow:'LỘ TRÌNH HỌC TOÁN',summary:roadmap.summary,image:roadmap.icon==='shapes'?'/assets/toan/geometry-v3.webp':roadmap.icon==='target'?'/assets/toan/exam-v3.webp':'/assets/toan/foundation-v6.png',imageAlt:'Minh họa hành trình khám phá và học Toán',notice:previewNotice,steps:roadmap.steps,stepTitle:'Từng bước trên hành trình',sections:[{title:'Cách tham khảo lộ trình',body:'Đọc mục tiêu và các bước bên dưới, đối chiếu với nội dung đang học. Có thể trao đổi với giáo viên để lựa chọn điểm bắt đầu phù hợp.'},{title:'Học liệu và tiến độ',body:'Bài học, bài tập, thời lượng và tiêu chí hoàn thành chưa được công bố. Trang không ghi nhận tiến độ hoặc kết quả học tập.'}],destination:'roadmaps',destinationLabel:'Xem tất cả lộ trình',context:`Lớp ${grade} · Lộ trình minh họa`};
 }
 if(['classes','materials','practice'].includes(kind)){
  const card=getCatalogCards(kind,grade).find(c=>c.id===id);if(!card)return null;
  const destinationLabel={classes:'Xem các lớp học mẫu',materials:'Xem danh mục tài liệu',practice:'Xem danh mục luyện đề'}[kind]!;
  return {title:card.title,eyebrow:card.label,summary:card.summary,image:card.image,imageAlt:`Minh họa ${kind==='classes'?'lớp học':kind==='materials'?'tài liệu':'luyện đề'} Toán`,notice:card.detail,steps:card.points,stepTitle:'Cấu trúc nội dung minh họa',sections:[{title:'Phạm vi bản xem trước',body:card.detail},{title:'Trước khi đưa vào sử dụng',body:'Nội dung chuyên môn, người phụ trách, điều kiện sử dụng và học liệu cần được xác minh và phê duyệt. Các thông tin tổ chức bên cạnh chỉ là dữ liệu mẫu, không phải dịch vụ đang cung cấp.'}],catalogIndex:card.index,destination:kind,destinationLabel,context:`Lớp ${grade} · Dữ liệu mẫu`};
 }
 if(kind==='teachers'){
  const teacher=teachers.find(t=>t.id===id);if(!teacher)return null;
  return {title:teacher.name,eyebrow:teacher.sample?'HỒ SƠ GIÁO VIÊN MINH HỌA':'GIÁO VIÊN ĐỒNG HÀNH',summary:teacher.role,image:'/assets/toan/educator-v3.webp',imageAlt:'Hình giáo viên minh họa, không phải chân dung người trong hồ sơ',notice:teacher.sample?'Hồ sơ giả định để xem bố cục, không đại diện cho giáo viên thật. Ảnh không phải chân dung người trong hồ sơ.':'Tên, vai trò và đơn vị do chủ hệ thống cung cấp. Ảnh chỉ là minh họa, không phải chân dung cô Nguyễn Thị Diện.',sections:[{title:'Đơn vị quản lý',body:teacher.unit},{title:'Thông tin hồ sơ',body:teacher.sample?'Đây là ví dụ minh họa cách giới thiệu giáo viên đồng hành. Danh tính, bằng cấp, kinh nghiệm và thông tin liên hệ thực chưa được công bố.':'Cô Nguyễn Thị Diện là chuyên gia, chủ Trung tâm Bồi dưỡng học sinh giỏi Vĩnh Xuân theo thông tin chủ hệ thống cung cấp. Tiểu sử chi tiết, bằng cấp và kinh nghiệm chờ xác minh trước khi công bố.'},{title:'Lớp phụ trách',body:'Chưa có danh sách lớp đã xác minh gắn với hồ sơ này. Các lớp trong danh mục chung là minh họa, không phải lớp của giáo viên trong hồ sơ.'},{title:'Thành tích và đánh giá',body:'Chưa có dữ liệu được xác minh. Không hiển thị số năm kinh nghiệm, số học sinh, kết quả hoặc đánh giá giả.'}],destination:'teachers',destinationLabel:'Xem danh sách giáo viên',context:'Hồ sơ đang hoàn thiện'};
 }
 if(kind==='topic'){
  const i=topicIds.indexOf(id);if(i<0)return null;
  return {title:topicNames[i],eyebrow:'CHUYÊN ĐỀ TOÁN',summary:`Tìm hiểu mạch nội dung ${topicNames[i].toLowerCase()} trong ngữ cảnh lớp ${grade}.`,image:i===1?'/assets/toan/geometry-v3.webp':'/assets/toan/books-detail.webp',imageAlt:'Minh họa sách và kiến thức Toán học',notice:previewNotice,sections:[{title:'Nội dung theo lớp đang chọn',body:`Các học liệu ${topicNames[i].toLowerCase()} cần được biên tập và lọc theo chương trình lớp ${grade}. Bản xem trước chưa có danh sách bài học thật.`},{title:'Chọn bước tiếp theo',body:'Tham khảo các lộ trình theo lớp để hình dung mục tiêu và trình tự. Không coi danh mục minh họa là chương trình học đã được phê duyệt.'}],destination:'roadmaps',destinationLabel:'Xem lộ trình theo lớp',context:`Lớp ${grade} · Chuyên đề minh họa`};
 }
 if(kind==='guide'&&Object.hasOwn(serviceDetails,id))return {...serviceDetails[id],context:'Thông tin đang chuẩn bị'};
 return null;
}
